#include <string.h>

/* Fibonacci with base-1e9 big integers so results match Python exactly. */
int main(int argc, char **argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s N\n", argv[0]); return 1; }
    long n = strtol(argv[1], NULL, 10);
    if (n < 0) { fprintf(stderr, "N must be >= 0\n"); return 1; }
    size_t cap = (size_t)(n / 43) + 2; /* fib(n) < 2^(0.695n); 1e9 ~ 2^29.9 */
    unsigned int *a = calloc(cap, sizeof *a), *b = calloc(cap, sizeof *b);
    if (!a || !b) { fprintf(stderr, "out of memory\n"); return 1; }
    size_t len = 1;
    a[0] = 0; b[0] = 1;
    for (long i = 0; i < n; i++) {
        /* (a, b) = (b, a + b): store a+b into a, then swap */
        unsigned int carry = 0;
        for (size_t j = 0; j < len; j++) {
            unsigned int s = a[j] + b[j] + carry;
            carry = s >= 1000000000u;
            a[j] = carry ? s - 1000000000u : s;
        }
